export function topScores(rows, limit = 5) {
  return rows
    .filter((r) => r.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, limit)
    .map((r) => r.name);
}

export function greet({ name = 'anon', locale = 'en-US' } = {}) {
  const hour = new Date().getHours();
  const part = hour < 12 ? 'morning' : 'evening';
  return `Good ${part}, ${name} (${locale})`;
}

