export async function getUser(id) {
  const res = await fetch(`/api/users/${id}`);
  if (!res.ok) throw new Error(`http ${res.status}`);
  const body = await res.json();
  return body?.data ?? null;
}

export class Counter {
  #counts = new Map();

  add(key) {
    this.#counts.set(key, (this.#counts.get(key) ?? 0) + 1);
    return this;
  }

  get top() {
    return [...this.#counts].sort((a, b) => b[1] - a[1])[0];
  }
}

export async function retry(fn, attempts = 3, delayMs = 250) {
  for (let i = 0; i < attempts; i += 1) {
    try {
      return await fn();
    } catch (err) {
      if (i === attempts - 1) throw err;
      await new Promise((resolve) => setTimeout(resolve, delayMs * 2 ** i));
    }
  }
}

export function debounce(fn, wait = 200) {
  let timer = null;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), wait);
  };
}

export function groupBy(items, keyFn) {
  return items.reduce((acc, item) => {
    const key = keyFn(item);
    (acc[key] ??= []).push(item);
    return acc;
  }, {});
}

export async function settleAll(urls) {
  const results = await Promise.allSettled(urls.map((u) => fetch(u)));
  return results.map((r, i) =>
    r.status === 'fulfilled'
      ? { url: urls[i], status: r.value.status }
      : { url: urls[i], error: String(r.reason) },
  );
}

export class Emitter {
  #handlers = new Map();

  on(event, fn) {
    const list = this.#handlers.get(event) ?? [];
    this.#handlers.set(event, [...list, fn]);
    return () => this.off(event, fn);
  }

  off(event, fn) {
    const list = this.#handlers.get(event) ?? [];
    this.#handlers.set(
      event,
      list.filter((h) => h !== fn),
    );
  }

  emit(event, payload) {
    for (const fn of this.#handlers.get(event) ?? []) fn(payload);
  }
}

export async function* paginate(url, pageSize = 50) {
  let cursor = null;
  do {
    const qs = new URLSearchParams({ limit: pageSize, ...(cursor && { cursor }) });
    const res = await fetch(`${url}?${qs}`);
    const { items, next } = await res.json();
    yield* items;
    cursor = next ?? null;
  } while (cursor);
}

export function memoize(fn, keyFn = (...args) => JSON.stringify(args)) {
  const cache = new Map();
  return (...args) => {
    const key = keyFn(...args);
    if (cache.has(key)) return cache.get(key);
    const value = fn(...args);
    cache.set(key, value);
    return value;
  };
}

export class LruCache {
  #map = new Map();

  constructor(limit = 128) {
    this.limit = limit;
  }

  get(key) {
    if (!this.#map.has(key)) return undefined;
    const value = this.#map.get(key);
    this.#map.delete(key);
    this.#map.set(key, value);
    return value;
  }

  set(key, value) {
    this.#map.delete(key);
    this.#map.set(key, value);
    if (this.#map.size > this.limit) {
      this.#map.delete(this.#map.keys().next().value);
    }
  }
}

const isPlain = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);

export function deepMerge(base, patch) {
  return Object.entries(patch).reduce(
    (acc, [key, value]) => ({
      ...acc,
      [key]: isPlain(value) && isPlain(acc[key]) ? deepMerge(acc[key], value) : value,
    }),
    { ...base },
  );
}

export async function mapLimit(items, limit, worker) {
  const out = new Array(items.length);
  let cursor = 0;

  const runners = Array.from({ length: Math.min(limit, items.length) }, async () => {
    while (cursor < items.length) {
      const index = cursor;
      cursor += 1;
      out[index] = await worker(items[index], index);
    }
  });

  await Promise.all(runners);
  return out;
}
